export interface XboxIconOptions {
  size?: number;
  className?: string;
  /** 无障碍标题；省略则视为装饰（aria-hidden） */
  title?: string;
}

export function xboxIcon(name: XboxIconName, opts: XboxIconOptions = {}): string {
  const size = opts.size ?? 24;
  const def = ICONS[name];
  const cls = ['xbx', `xbx-${def.mode}`, opts.className].filter(Boolean).join(' ');
  const a11y = opts.title
    ? `role="img" aria-label="${opts.title.replace(/"/g, '&quot;')}"`
    : 'aria-hidden="true"';

  // 填充字形只填不描边；线条图标只描边不填充
  const paint =
    def.mode === 'fill'
      ? 'fill="currentColor" stroke="none"'
      : 'fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"';

  return (
    `<svg class="${cls}" width="${size}" height="${size}" viewBox="0 0 24 24" ${paint} ${a11y}>` +
    def.body +
    '</svg>'
  );
}

/** 全部图标名（顺序即预览顺序） */
export const XBOX_ICON_NAMES = Object.keys(ICONS) as XboxIconName[];

export const XBOX_ICON_CSS = `
.xbx { display: block; flex: 0 0 auto; }
`;
